class LmdbStoreBindingSetCompatibilityIndexTest {
	@TempDir
	File dataDir;

	@Test
	void mapDbIndexPreservesLmdbValuesAcrossConfiguredSpill() throws Exception {
		LmdbStore store = new LmdbStore(dataDir);
		store.setIterationCacheSyncThreshold(1);
		store.init();
		try {
			ValueFactory valueFactory = store.getValueFactory();
			List<Value> values = values(valueFactory);
			try (CollectionFactory factory = store.getCollectionFactory().get();
					BindingSetCompatibilityIndex index = factory.createBindingSetCompatibilityIndex(List.of("value"))) {
				assertInstanceOf(MapDb3CollectionFactory.class, factory);
				for (int i = 0; i < values.size(); i++) {
					index.add(row(valueFactory, values.get(i), i));
				}

				for (int i = 0; i < values.size(); i++) {
					List<BindingSet> matches = collect(index.candidateRows(probe(values.get(i))));
					assertEquals(1, matches.size());
					assertEquals(values.get(i), matches.get(0).getValue("value"));
					assertInstanceOf(LmdbValue.class, matches.get(0).getValue("value"));
					assertEquals("row-" + i, matches.get(0).getValue("label").stringValue());
				}
			}
		} finally {
			store.shutDown();
			LmdbTestUtil.deleteDir(dataDir);
		}
	}

	@Test
	void mapDbIndexPreservesPersistedLazyDatasetValuesInNonKeyBindings() throws Exception {
		LmdbStore store = new LmdbStore(dataDir);
		store.setIterationCacheSyncThreshold(1);
		store.init();
		try {
			ValueFactory valueFactory = store.getValueFactory();
			Resource subject = valueFactory.createIRI("urn:test:lmdb-index:dataset-subject");
			IRI predicate = valueFactory.createIRI("urn:test:lmdb-index:dataset-predicate");
			String expectedLabel = "persisted lazy LMDB payload " + "x".repeat(128);
			Literal expectedPayload = valueFactory.createLiteral(expectedLabel);
			persistDatasetStatement(store, subject, predicate, expectedPayload);

			ValueStore valueStore = (ValueStore) valueFactory;
			// The public statement connection materializes values, so read the committed dictionary value lazily here.
			long payloadId = valueStore.getId(expectedPayload);
			assertNotEquals(LmdbValue.UNKNOWN_ID, payloadId);
			assertFalse(ValueIds.isInlined(payloadId));
			LmdbValue lazyReadBack = valueStore.getLazyValue(payloadId);
			assertFalse(lazyReadBack.isInitialized());

			Value key = valueFactory.createIRI("urn:test:lmdb-index:dataset-key");
			try (CollectionFactory factory = store.getCollectionFactory().get();
					BindingSetCompatibilityIndex index = factory.createBindingSetCompatibilityIndex(List.of("key"))) {
				assertInstanceOf(MapDb3CollectionFactory.class, factory);
				MapBindingSet row = new MapBindingSet();
				row.addBinding("key", key);
				row.addBinding("payload", lazyReadBack);
				index.add(row);

				List<BindingSet> matches = collect(index.candidateRows(probe("key", key)));
				assertEquals(1, matches.size());
				LmdbValue indexedPayload = assertInstanceOf(LmdbValue.class, matches.get(0).getValue("payload"));
				assertEquals(expectedPayload, indexedPayload);
				assertEquals(expectedLabel, ((Literal) indexedPayload).getLabel());
				assertTrue(indexedPayload.isInitialized());
			}
		} finally {
			store.shutDown();
			LmdbTestUtil.deleteDir(dataDir);
		}
	}

	private static void persistDatasetStatement(LmdbStore store, Resource subject, IRI predicate, Value expected)
			throws Exception {
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(subject, predicate, expected);
			connection.commit();
		}
	}

	private static List<Value> values(ValueFactory valueFactory) {
		Value iri = valueFactory.createIRI("urn:test:lmdb-index:iri");
		Value literal = valueFactory.createLiteral("lmdb literal", "en");
		Value bnode = valueFactory.createBNode("lmdb-index-bnode");
		Value triple = valueFactory.createTripleTerm((Resource) iri,
				valueFactory.createIRI("urn:test:lmdb-index:predicate"), literal);
		return List.of(iri, literal, bnode, triple);
	}

	private static MapBindingSet row(ValueFactory valueFactory, Value value, int index) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", value);
		row.addBinding("label", valueFactory.createLiteral("row-" + index));
		return row;
	}

	private static MapBindingSet probe(Value value) {
		MapBindingSet probe = new MapBindingSet();
		probe.addBinding("value", value);
		return probe;
	}

	private static MapBindingSet probe(String bindingName, Value value) {
		MapBindingSet probe = new MapBindingSet();
		probe.addBinding(bindingName, value);
		return probe;
	}

	private static List<BindingSet> collect(Iterator<BindingSet> rows) {
		List<BindingSet> result = new ArrayList<>();
		rows.forEachRemaining(result::add);
		return result;
	}
}
